#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main() {
    char s[1000005];
    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    size_t len = strlen(s);
    if (len > 0 && s[len-1] == '\n') {
        s[len-1] = '\0';
        len--;
    }

    if (len == 0) {
        printf("\n");
        return 0;
    }

    char *result = malloc((len + 1) * sizeof(char));
    if (result == NULL) {
        return 1;
    }

    int front = 0;
    int back = len - 1;
    int dir = 0; // 0: take from front, 1: take from back

    for (int i = 0; i < len; i++) {
        if (dir == 0) {
            result[i] = s[front++];
        } else {
            result[i] = s[back--];
        }
        dir = 1 - dir;
    }

    result[len] = '\0';
    printf("%s\n", result);
    free(result);
    return 0;
}
